<script setup>
import { computed, ref, watch, nextTick } from 'vue'
import UiIcon from '../../../shared/components/UiIcon.vue'
import TermHint from '../../../shared/components/TermHint.vue'
import PlannerScenarioAssessment from './PlannerScenarioAssessment.vue'
import PlanningImpactReport from './PlanningImpactReport.vue'
import DemandScenarioControls from './DemandScenarioControls.vue'
import SitingReferencePanel from './SitingReferencePanel.vue'
import LocalSitingSearch from './LocalSitingSearch.vue'
import UiDrawer from '../../../shared/components/UiDrawer.vue'
import { confirmAction, showError, showToast } from '../../../shared/feedback/feedback.js'
import { useFacilitySandbox } from '../composables/useFacilitySandbox.js'
import { CONSTRUCTION_SURVEY_FIELDS } from '../models/stationPlanImpact.js'

const props = defineProps({ stations: { type: Array, default: () => [] }, features: { type: Array, default: () => [] },
  demandPois: { type: Array, default: () => [] }, activityPois:Array, demandModel:Object, scenarioId:String,mapMode:String, boundary: Object, constructionFactors:Object,constructionOptions:Object,loading: Boolean, active: Boolean, panelVisible: { type: Boolean, default: true }, locating: Boolean, locationError: String,
  siteContext:Object,roads:Array,contextLoading:Boolean,contextError:String })
const emit = defineEmits(['open-layout', 'preview', 'search-change', 'focus-point', 'focus-location', 'focus-place', 'locate', 'district','scenario-change','map-mode-change','planning-assist','construction-options','focus-reference','retry-context'])
const { tool, stage, center, locationName, radiusMeters, dataScope, dataset, baseline, pointBaseline, comparisonMetric,
  additions, removedIds, selected, result, running, dirty, error, notice, preview,
  setLocation, useDistrict, select, add, removeAddition, toggleCandidate, includeCandidate, toggleRemoval, updateSelected, replaceRoadPlan, mapClick: editMapClick, run, reset } = useFacilitySandbox(props)
const localSearch=ref(null),localDrawerOpen=ref(false)
async function searchSiting(coordinates,name){
  if(running.value || props.loading)return false
  emit('open-layout')
  settingsOpen.value=false;localDrawerOpen.value=true;tool.value='add';stage.value='after'
  await nextTick()
  return localSearch.value?.search(coordinates,name)
}
async function mapClick(event){
  if(!props.active || running.value || props.loading)return
  if(tool.value!=='inspect')emit('open-layout')
  if(event.candidateId && tool.value==='add'){localDrawerOpen.value=true;localSearch.value?.choose(event.candidateId);return}
  if(tool.value==='add' && !event.sandboxId && !event.removedId && event.stationId==null){searchSiting(event.coordinates);return}
  if(tool.value==='remove' && !event.removedId && (event.sandboxId || event.stationId!=null)){
    if(!await confirmAction('确认从当前方案中删除此站点？',event.anchor))return
    if(!props.active || running.value || props.loading)return
  }
  editMapClick(event)
}
function confirmLocalSite(feature){
  if(!canEdit.value)return
  const added=add(feature.geometry.coordinates,{...feature.properties,planningSource:'local-buffer'})
  if(added){editorOpen.value=true;localDrawerOpen.value=false;showToast('候选已加入共同方案')}
}
async function requestRemoveAddition(id,event){if(await confirmAction('确认删除这个新增点位？',event.currentTarget))removeAddition(id)}
async function requestReset(event){if(await confirmAction('确认清空当前新增与移除方案？',event.currentTarget))reset()}
watch(error,value=>{if(value)showError(value,'方案调整未完成')})
const editorOpen = ref(false), resultEl = ref(null), requestedLocation = ref(false), settingsOpen = ref(false), referenceOpen = ref(false)
const assistantOpen = ref(false)
watch([settingsOpen,assistantOpen,()=>props.active,()=>props.panelVisible],([settings,assistant,active,visible])=>emit('planning-assist',active && visible && settings && assistant),{immediate:true})
watch([()=>props.active,()=>props.panelVisible],([active,visible])=>{
  if(active&&visible)return
  settingsOpen.value=false;editorOpen.value=false;referenceOpen.value=false;localDrawerOpen.value=false
})
watch(selected,value=>{if(value)editorOpen.value=true})
const selectedGrid=computed(()=>selected.value ? dataset.value.features.find(feature=>String(feature.properties.id)===String(selected.value.properties.gridId || selected.value.properties.planningGridId)) : null)
const selectedSiteChecks=computed(()=>{
  const properties={...selectedGrid.value?.properties,...props.constructionFactors?.[String(selectedGrid.value?.properties.id)]}
  return [...CONSTRUCTION_SURVEY_FIELDS.map(field=>({label:field.label,value:properties[field.key]===true?'已填满足':properties[field.key]===false?'不满足':'待核查'})),
    {label:'公共可用泊位',value:properties.parkingSpaces==null?'待核查':properties.parkingSpaces+' 个'},
    {label:'配变可用余量',value:properties.availableKva==null?'待核查':properties.availableKva+' kVA'}]
})
function returnToEditor(){settingsOpen.value=false}
function updateConstructionOption(key,raw){
  const value=Number(raw)
  if(!Number.isFinite(value) || value<0 || key==='radius' && value>3000 || key==='powerFactor' && (value<=0 || value>1))return
  emit('construction-options',{radius:0,minimumSpaces:0,powerFactor:.9,...props.constructionOptions,[key]:value})
}
const savedPlans=ref([]),planName=ref(''),snapshotNotice=ref('')
const comparisonPlans=computed(()=>savedPlans.value.filter(item=>item.impact.contextKey===result.value?.planningImpact.contextKey&&item.scope===JSON.stringify([center.value,radiusMeters.value])))
function savePlan(){if(!result.value||dirty.value)return;const name=planName.value.trim()||'备选方案 '+(savedPlans.value.length+1);savedPlans.value=[...savedPlans.value.slice(-3),{name,impact:structuredClone(JSON.parse(JSON.stringify(result.value.planningImpact))),scope:JSON.stringify([center.value,radiusMeters.value]),piles:additions.value.reduce((sum,row)=>sum+row.properties.pileCount,0),kw:additions.value.reduce((sum,row)=>sum+row.properties.pileCount*row.properties.powerKw,0),removed:removedIds.value.length}];planName.value='';snapshotNotice.value='已保留本次结果；继续调整地图后重新分析，可对照备选。'}
watch(preview, value => emit('preview', value), { immediate: true })
watch(center, value => { if (value) { requestedLocation.value = false; focusLocation() } })
watch(radiusMeters, () => { if (center.value) focusLocation() })
watch(result, async value => { if (value) { await nextTick(); resultEl.value?.scrollIntoView({ block: 'start', behavior: 'smooth' }) } })
const shownAssessment = computed(() => result.value && !dirty.value && stage.value === 'after' ? result.value.after : baseline.value)
const shownPoint = computed(() => result.value && !dirty.value ? stage.value === 'after' ? result.value.diagnostics.pointAfter : result.value.diagnostics.pointBefore : pointBaseline.value)
const metric = (value, digits = 1) => value == null ? '资料不足' : value.toFixed(digits)
const percent = value => value == null ? '资料不足' : value.toFixed(1) + '%'
const savedDistance = value => value == null ? '待核查' : Math.abs(value)<1 ? '基本不变' : (value>0?'缩短 ':'增加 ')+Math.round(Math.abs(value))+' m'
const placeDistance = value => value == null ? '暂无站' : Math.round(value)+' m'
const constructionLabel = status => ({fail:'建设条件存在不满足项',pending:'建设资料待核查','scenario-pass':'已填情景条件满足','no-new-sites':'本方案没有新增站点'})[status] || '建设条件待核查'
const diagnostics = computed(() => result.value?.diagnostics)
const canEdit = computed(() => !running.value && !props.loading)
function focusLocation() { emit('focus-location', { center: center.value, radiusMeters: radiusMeters.value }) }
function locate() { requestedLocation.value = true; emit('locate') }
function district() { useDistrict(); emit('district') }
function edit(feature) { select(feature.properties.id); tool.value = 'add'; stage.value = 'after'; editorOpen.value = true; emit('focus-point', feature) }
function compareStage(value) { stage.value = value; tool.value = 'inspect' }
const updateNumber = (field, value) => updateSelected(field, value === '' ? null : Number(value))
function addCandidate({ row, spec }) {
  return searchSiting(row?.location?.geometry.coordinates,row?.areaName)
}
function receiveCandidate(row) {
  return searchSiting(row?.location?.geometry.coordinates,row?.areaName)
}
function setDataScope(value) { if (!running.value && ['recorded','all'].includes(value)) dataScope.value = value }
defineExpose({ mapClick, searchSiting, setLocation, addCandidate, receiveCandidate, setDataScope, returnToEditor, replaceRoadPlan })
</script>

<template>
  <section class="right-card facility-suggestions local-planning simulation-workbench" aria-label="设施布局模拟沙盘">
    <header class="simulation-header"><div><span class="simulation-eyebrow">共同方案</span><h2>布局规划</h2><p>选场地、调整站点，再分析方案效果。</p></div><button class="simulation-settings-button" :aria-expanded="settingsOpen" aria-controls="simulation-settings" @click="settingsOpen=true;editorOpen=false;referenceOpen=false"><UiIcon name="settings" :size="17" />设置</button></header>
    <div class="siting-panel-search"><slot name="plan-search" /></div>
    <p v-if="requestedLocation && locationError" class="sandbox-error" role="alert">{{ locationError }}</p><p v-if="notice" class="local-notice" role="status">{{ notice }}</p>
    <UiDrawer :open="settingsOpen && active && panelVisible" title="规划设置" label="规划设置抽屉" close-label="关闭规划设置" @close="settingsOpen=false">
    <section id="simulation-settings" class="simulation-settings-panel local-planning" aria-label="方案推演设置">
      <details class="planning-reference-tools"><summary>公开参考资料与来源</summary><SitingReferencePanel catalog :data="siteContext" :loading="contextLoading" :error="contextError" @retry="emit('retry-context')" /></details>
      <h3>落点与判定</h3><p class="local-note">地图点击建立搜索缓冲区，不直接建站。圈内停车及场地记录经过道路、水域、环境用地与已知建设条件筛查，确认时再次核查。</p><div class="local-scope"><label>最小站间距（m，0 为不限制）<input type="number" min="0" max="3000" :value="constructionOptions?.radius ?? 0" aria-label="规划最小站间距" @change="updateConstructionOption('radius',$event.target.value)" /></label><label>最少公共泊位<input type="number" min="0" :value="constructionOptions?.minimumSpaces ?? 0" aria-label="规划最少泊位" @change="updateConstructionOption('minimumSpaces',$event.target.value)" /></label></div><p class="local-note">这些是可调整的情景阈值，不是当地建设标准；默认不设置最小站间距。服务比较采用 1 km 直线范围，也仅是模型假设，不决定新增位置。</p><details :open="assistantOpen" class="local-more planning-reference-tools" @toggle="assistantOpen=$event.target.open"><summary>区域筛选与网格候选参考（可选）</summary><slot name="planning-tools" /></details><h3>范围与数据（可选）</h3>
      <div class="local-location-actions" role="group" aria-label="模拟范围"><button :class="{active:!center}" :disabled="!canEdit" @click="district">全区布局</button><button :disabled="!canEdit" @click="tool='locate';stage='after';settingsOpen=false">地图重选范围</button><button :disabled="!canEdit || locating" @click="locate">{{ locating ? '定位中…' : '当前位置' }}</button></div>
      <div class="local-scope"><label v-if="center">周边半径<select v-model.number="radiusMeters" aria-label="周边分析半径" :disabled="running"><option :value="500">500 米</option><option :value="1000">1 公里</option><option :value="2000">2 公里</option><option :value="3000">3 公里</option><option :value="5000">5 公里</option></select></label><label>站点数据<select v-model="dataScope" aria-label="分析数据范围" :disabled="running"><option value="recorded">已记录点位</option><option value="all">含演示点位</option></select></label></div>
      <p class="local-note">切换评价范围或站点数据会重置草稿；候选搜索圈与评价范围独立，移动搜索中心不会清空已有方案。</p>
      <DemandScenarioControls v-if="demandModel" :scenario-id="scenarioId" :map-mode="mapMode" :features="demandModel.features" :disabled="running" @scenario-change="emit('scenario-change',$event)" @map-mode-change="emit('map-mode-change',$event)" />
      <h3>地图与计算口径</h3><label class="simulation-setting-field">地图比较指标<select v-model="comparisonMetric" aria-label="地图评价指标"><option value="service">充电服务评分变化</option><option value="supply">需求与站点数量差距变化</option></select></label>
      <p class="local-note">按同一份估计需求比较前后配置。服务距离采用 1 km 直线，站点能力按功率与距离在需求地点之间分配；不会据此生成实际订单、排队或收入。</p>
      <section v-if="shownPoint" class="local-current"><h3>定位服务指数</h3><div class="local-current-metrics"><article><TermHint term="accessibleService" label="附近充电服务评分" /><strong>{{ metric(shownPoint.serviceIndex) }}</strong></article><article><TermHint term="backupService" label="主要站点退出后的服务评分" /><strong>{{ metric(shownPoint.backupIndex) }}</strong></article></div><p class="local-note">用于模型内部比较，不是实测服务满足率。</p></section>
      <template v-if="result && !dirty"><h3>完整核查与计算明细</h3><PlanningImpactReport :impact="result.planningImpact" @focus-place="emit('focus-place',$event)" @focus-station="emit('focus-place',$event)" /><details class="local-more"><summary>辅助服务指数、洛伦兹曲线与运营参数</summary><PlannerScenarioAssessment :points="additions" :result="result" :dirty="dirty" /><div v-if="diagnostics.candidates.length || diagnostics.removals.length" class="local-directions"><p v-if="diagnostics.candidates.length">辅助补点建议：<button @click="emit('focus-place',diagnostics.candidates[0].feature)">{{ diagnostics.candidates[0].name }}</button><small>同配置补 1 桩 / 60 kW，范围内加权服务预计 +{{ metric(diagnostics.candidates[0].estimatedGain) }} 分。</small></p><p v-if="diagnostics.removals.length">辅助撤站核查：<button @click="emit('focus-point',diagnostics.removals[0].feature)">{{ diagnostics.removals[0].feature.properties.name }}</button><small>单独撤去，范围内加权服务预计损失 {{ metric(diagnostics.removals[0].estimatedLoss) }} 分。</small></p></div><table class="local-comparison"><thead><tr><th>辅助评价</th><th>调整前</th><th>调整后</th></tr></thead><tbody><tr><th>薄弱需求占比</th><td>{{ percent(diagnostics.before.weakDemandShare) }}</td><td>{{ percent(diagnostics.after.weakDemandShare) }}</td></tr><tr><th>薄弱端服务</th><td>{{ metric(diagnostics.before.underservedAccess) }}</td><td>{{ metric(diagnostics.after.underservedAccess) }}</td></tr><tr><th>服务不均衡</th><td>{{ metric(diagnostics.before.inequality,3) }}</td><td>{{ metric(diagnostics.after.inequality,3) }}</td></tr></tbody></table><p class="local-note">采用 Gaussian 2SFCA 可达性估计；能力未知、模拟配置及网格估计需求在完整核查中单独说明。</p></details></template>
    </section>
    </UiDrawer>
    <button class="open-local-siting" type="button" :disabled="!canEdit" @click="localDrawerOpen=true;settingsOpen=false;editorOpen=false;referenceOpen=false;tool='add';stage='after'"><UiIcon name="pin" :size="18" /><span>选择周边区域<small>在地图上选场地，确认后加入方案</small></span><span aria-hidden="true">→</span></button>
    <UiDrawer :open="localDrawerOpen && active && panelVisible && !settingsOpen" title="选择周边区域" @close="localDrawerOpen=false"><LocalSitingSearch ref="localSearch" :active="active" :disabled="!canEdit" :boundary="boundary" :additions="additions" :removed-ids="removedIds" :factors="constructionFactors" :constraints="constructionOptions" :data-scope="dataScope" :scenario-id="scenarioId" @change="emit('search-change',$event)" @confirm="confirmLocalSite" @focus="emit('focus-point',$event)" /></UiDrawer>
      <div class="simulation-plan-stats" aria-label="当前共同方案"><article><span>新增站点</span><strong>{{ additions.length }}<small>处</small></strong></article><article><span>新增充电桩</span><strong>{{ additions.reduce((total,feature)=>total+(feature.properties.pileCount || 0),0) }}<small>个</small></strong></article><article><span>移除站点</span><strong>{{ removedIds.length }}<small>处</small></strong></article></div>
      <div class="simulation-scope-line"><UiIcon name="pin" :size="13" /><span>{{ center ? locationName+'周边 '+radiusMeters+' m' : '魏都区 · 全区方案' }}</span><small>{{ dataScope==='recorded' ? '已记录站点' : '含演示站点' }}</small></div>
      <section class="simulation-edit-card" aria-label="编辑共同方案"><div class="simulation-section-heading"><h3>调整站点</h3><button class="simulation-text-button" :disabled="!canEdit || !additions.length && !removedIds.length" @click="requestReset">清空方案</button></div><div class="sandbox-toolbar" role="group" aria-label="沙盘点位编辑工具"><button :class="{active:tool==='add'}" :aria-pressed="tool==='add'" :disabled="!canEdit" @click="tool='add';stage='after'"><UiIcon name="plus" :size="15" />新增站点</button><button :class="{active:tool==='remove'}" :aria-pressed="tool==='remove'" :disabled="!canEdit" @click="tool='remove';stage='after'"><UiIcon name="minus" :size="15" />移除站点</button><button :class="{active:tool==='inspect'}" :aria-pressed="tool==='inspect'" :disabled="!canEdit" @click="tool='inspect'">查看地图</button></div><p class="sandbox-help">{{ tool==='locate' ? '点击地图设置周边范围。' : tool==='inspect' ? '点击地图上的站点或地点查看详情。' : tool==='add' ? '点击地图建立搜索圈，选择候选并确认新增；橙色站点可修改配置。' : '点击已有站点移除，再点红色站点可恢复。' }}</p>
      <div v-if="!additions.length && !removedIds.length" class="simulation-empty"><UiIcon name="pin" :size="21" /><div><b>从地图上选一个场地</b><p>确认候选后，会加入当前方案。</p></div></div>
      <ul v-if="additions.length" class="sandbox-point-list" aria-label="新增点位列表"><li v-for="feature in additions" :key="feature.properties.id" :class="{selected:selected?.properties.id===feature.properties.id}"><button class="sandbox-point-select" :disabled="running" @click="edit(feature)"><i></i><span>{{ feature.properties.name }}<small>{{ feature.properties.planningSource==='local-buffer' ? '周边约束候选' : '规划站点' }} · {{ feature.properties.pileCount ?? '—' }} 桩 × {{ feature.properties.powerKw ?? '—' }} kW</small></span></button><button class="sandbox-remove" :aria-label="'移除 '+feature.properties.name" :disabled="running" @click="requestRemoveAddition(feature.properties.id,$event)"><UiIcon name="close" :size="14" /></button></li></ul>
      <div v-if="removedIds.length" class="simulation-removed-list"><button v-for="id in removedIds" :key="id" :disabled="running" @click="toggleRemoval(id)"><span>{{ dataset.stations.find(feature=>String(feature.properties.id)===id)?.properties.name || id }}</span><small>恢复</small></button></div>
      <button v-if="selected" type="button" class="simulation-site-detail" :aria-expanded="editorOpen" @click="editorOpen=true;settingsOpen=false;referenceOpen=false"><span><b>{{ selected.properties.name }}</b><small>{{ selected.properties.pileCount ?? '—' }} 桩 · {{ selected.properties.powerKw ?? '—' }} kW / 桩</small></span>配置与核查<UiIcon name="arrow-right" :size="16" /></button>
      </section>
      <UiDrawer :open="editorOpen && !!selected && active && panelVisible && !settingsOpen && !localDrawerOpen" title="站点配置与核查" label="站点配置抽屉" close-label="关闭站点配置" @close="editorOpen=false">
      <section v-if="selected" class="sandbox-parameters" aria-label="站点配置"><h3>{{ selected.properties.name }}</h3><fieldset :disabled="running"><label class="sandbox-name">名称<input :value="selected.properties.name" maxlength="60" aria-label="模拟点位名称" @input="updateSelected('name',$event.target.value)" /></label><label>类型<select :value="selected.properties.chargeType" aria-label="模拟充电分类" @change="updateSelected('chargeType',$event.target.value)"><option value="fast">快充</option><option value="regular">普通充电</option></select></label><label>桩数<input type="number" min="1" max="1000" step="1" :value="selected.properties.pileCount" aria-label="模拟桩数" @input="updateNumber('pileCount',$event.target.value)" /></label><label class="sandbox-name">单桩功率（kW）<input type="number" min=".1" max="1000" step=".1" :value="selected.properties.powerKw" aria-label="模拟单桩功率" @input="updateNumber('powerKw',$event.target.value)" /></label></fieldset></section>
      <section v-if="selected" class="selected-site-checks" aria-label="当前新增位置核查"><p><b>新增位置</b> {{ selected.geometry.coordinates.map(value=>value.toFixed(6)).join('，') }}</p><SitingReferencePanel :data="siteContext" :roads="roads" :coordinates="selected.geometry.coordinates" :loading="contextLoading" :error="contextError" @retry="emit('retry-context')" @focus="emit('focus-reference',$event)" /><details class="construction-review"><summary>建设条件核查</summary><dl><div v-for="check in selectedSiteChecks" :key="check.label"><dt>{{ check.label }}</dt><dd>{{ check.value }}</dd></div></dl><small>资料未知不等于可建设。初始 1 桩 × 60 kW 为可修改的模拟配置。</small></details></section>
      </UiDrawer>
      <button type="button" class="simulation-reference-button" :aria-expanded="referenceOpen" @click="referenceOpen=true;settingsOpen=false;editorOpen=false">直线评估与备选方案<UiIcon name="arrow-right" :size="14" /></button>
      <UiDrawer :open="referenceOpen && active && panelVisible && !settingsOpen && !editorOpen && !localDrawerOpen" title="直线评估与备选方案" label="直线评估抽屉" close-label="关闭直线评估" @close="referenceOpen=false">
      <div class="sandbox-run-row"><span role="status">{{ running ? '正在计算直线参考…' : result ? dirty ? '方案已更新，直线参考待重算' : '直线参考已分析' : '此处仅计算旧直线参考，不代表道路时间' }}</span><button class="sandbox-run" :disabled="!canEdit || !additions.length && !removedIds.length" @click="run"><UiIcon name="chart" :size="16" />{{ running ? '分析中…' : '直线参考分析' }}</button></div>
