lder="为这个方案取个名字" maxlength="30" /><button @click="savePlan">保留结果</button></div><p class="local-note" role="status">{{ snapshotNotice }}</p><div v-if="comparisonPlans.length" class="pss-table-wrap"><table class="local-comparison"><thead><tr><th>方案</th><th>新覆盖需求</th><th>平均距站缩短</th></tr></thead><tbody><tr v-for="(plan,index) in comparisonPlans" :key="index"><th>{{ plan.name }} <button aria-label="删除备选结果" @click="savedPlans=savedPlans.filter(item=>item!==plan)">×</button></th><td>{{ percent(plan.impact.districtNewlyReachableShare) }}</td><td>{{ metric(plan.impact.districtSavedMeters,0) }} m</td></tr></tbody></table></div></details></template></section>
